{"path":"test_rw_validate.py","content":"import os
import pytest
from rw_validate import validate_extra_rw


@pytest.fixture
def home():
    return "/home/user"


@pytest.fixture
def protected():
    return ["/home/user/secrets", "/home/user/private"]


class TestValidateExtraRw:
    def test_nested_path_under_home_outside_protected_returns_true(self, home, protected):
        """(a) A plain nested path under home and outside protected returns True."""
        entry = "/home/user/documents/file.txt"
        assert validate_extra_rw(entry, home, protected) is True

    def test_entry_equals_home_returns_false(self, home, protected):
        """(b) entry == home returns False."""
        entry = home
        assert validate_extra_rw(entry, home, protected) is False

    def test_path_outside_home_returns_false(self, home, protected):
        """(c) A path outside home entirely returns False."""
        entry = "/etc/passwd"
        assert validate_extra_rw(entry, home, protected) is False

    def test_path_inside_protected_entry_returns_false(self, home, protected):
        """(d) A path inside one of the protected entries returns False."""
        entry = "/home/user/secrets/passwords.txt"
        assert validate_extra_rw(entry, home, protected) is False
